        builder.Property(e => e.Method).HasColumnName("method").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.NotifiedBy).HasColumnName("notified_by");
        builder.Property(e => e.NotifiedByName).HasColumnName("notified_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
